
import { nextTick } from 'vue'
import VIcon from './icon/VIcon.vue'
import VLoading from './VLoading.vue'

const isTaintedCanvas = (canvas: HTMLCanvasElement) => {
  if (!canvas.width || !canvas.height) {
    return false
  }
  try {
    canvas.getContext('2d').getImageData(0, 0, 1, 1)
  } catch {
    return true
  }
  return false
}

export default Vue.extend({
  name: 'CanvasViewer',
  components: {
    VIcon,
    VLoading,
  },
  data() {
    return {
      open: false,
      keyHandler: null,
      canvas: <HTMLCanvasElement>null,
      filename: '',
      blobUrl: '',
      blobStatus: '',
      downloadMessage: '',
      loadingError: false,
    }
  },
  mounted() {
    this.keyHandler = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        this.open = false
      }
    }
    document.addEventListener('keydown', this.keyHandler)
  },
  beforeDestroy() {
    document.removeEventListener('keydown', this.keyHandler)
  },
  methods: {
    detectOutside(e: MouseEvent) {
      if (e.target === this.$el || e.target === this.$refs.viewer) {
        this.open = false
      }
    },
    async setCanvas(canvas: HTMLCanvasElement, update = false) {
      if (!update && canvas === this.canvas) {
        return false
      }
      if (this.blobUrl) {
        URL.revokeObjectURL(this.blobUrl)
      }
      this.canvas = canvas
      this.blobUrl = null
      this.filename = null
      const container: HTMLElement = this.$refs.canvasContainer
      container.innerHTML = ''
      container.appendChild(canvas)
      await nextTick()
      return new Promise<boolean>(resolve => {
        requestAnimationFrame(() => {
          resolve(true)
        })
      })
    },
    setDownloadError(message: string) {
      this.blobStatus = 'error'
      this.downloadMessage = message
    },
    async setDownloadable(filename: string) {
      if (!this.canvas) {
        throw new Error('[CanvasViewer] Canvas not ready')
      }
      if (!filename) {
        return Promise.resolve()
      }
      this.filename = filename
      this.blobStatus = 'wait'
      this.downloadMessage = '正在创建图片……'
      await nextTick()
      if (isTaintedCanvas(this.canvas)) {
        this.setDownloadError('无法下载图片：快照图 CDN 未允许跨域, 画布被污染, 无法导出下载')
        throw new Error('[CanvasViewer] Failed to create image from tainted canvas')
      }
      return new Promise<void>((resolve, reject) => {
        requestAnimationFrame(() => {
          this.canvas.toBlob(blob => {
            if (!blob) {
              this.setDownloadError('无法下载图片：为 Canvas 创建图片失败')
              reject(new Error('[CanvasViewer] Failed to create image from canvas'))
            } else {
              this.blobStatus = 'ready'
              this.downloadMessage = `下载 ${filename}`
              this.blobUrl = URL.createObjectURL(blob)
              resolve()
            }
          }, 'image/jpeg')
        })
      })
    },
    setLoadingMessage(msg: string | Error) {
      if (msg instanceof Error) {
        msg = msg.message
        this.loadingError = true
      } else {
        this.loadingError = false
      }
      this.$refs.vLoading.config.content = msg
    },
  },
})
